enum {
    PROPERTY_OP_GET = 0,
    PROPERTY_OP_SET,
    PROPERTY_OP_DELETE,
    PROPERTY_OP_CLEAR,
    PROPERTY_OP_COMMIT,
};

struct uv_property_s {
    uv_work_t work_req;
    uv_property_cb cb;
    void* arg;
    uint8_t op;
    char* key;
    char* value;
    char* default_value;
    int status;
};
typedef struct uv_property_s uv_property_t;

static void uv_property_clear_cb(const char* key, const char* value, void* cookie)
{
    property_delete(key);
