<template>
  <div class="clock-page" style="opacity: {{ pageOpacity }}; margin-left: {{ pageOffset }}px; margin-top: {{ pageOffsetY }}px;" @swipe="handleSwipe" @touchstart="handleTouchStart" @touchmove="handleTouchMove" @touchend="handleTouchEnd">
    <div class="face-shell" style="background-color: {{ faceBackground }}; opacity: {{ faceOpacity }}; margin-left: {{ faceOffset }}px;">
      <div class="face-header">
        <text class="face-title" style="color: {{ faceAccent }}">{{ faceName }}</text>
        <div class="face-dots">
          <div class="face-dot" for="{{ faceDots }}" style="width: {{ $item.width }}px; background-color: {{ $item.color }};"></div>
        </div>
      </div>

      <sportface
        if="{{ faceSportVisible }}"
        display-month="{{ displayMonth }}"
        display-date="{{ displayDate }}"
        display-minutes="{{ displayMinutes }}"
        display-hours="{{ displayHours }}"
        face-accent="{{ faceAccent }}"
        battery-percent="{{ batteryPercent }}"
        battery-width="{{ batteryWidth }}"
        battery-color="{{ batteryColor }}"
        heart-rate-data="{{ heartRateData }}"
        current-heart-rate="{{ currentHeartRate }}"
        steps-text="{{ stepsText }}"
        steps-goal-text="{{ stepsGoalText }}">
      </sportface>

      <simpleface
        if="{{ faceSimpleVisible }}"
        display-week="{{ displayWeek }}"
        display-month="{{ displayMonth }}"
        display-date="{{ displayDate }}"
        display-hours="{{ displayHours }}"
        display-minutes="{{ displayMinutes }}"
        face-accent="{{ faceAccent }}"
        goal-percent="{{ goalPercent }}"
        steps-text="{{ stepsText }}"
        current-heart-rate="{{ currentHeartRate }}"
        battery-percent="{{ batteryPercent }}"
        battery-color="{{ batteryColor }}">
      </simpleface>

      <dashboardface
        if="{{ faceDashboardVisible }}"
        display-week="{{ displayWeek }}"
        display-month="{{ displayMonth }}"
        display-date="{{ displayDate }}"
        display-hours="{{ displayHours }}"
        display-minutes="{{ displayMinutes }}"
        face-accent="{{ faceAccent }}"
        steps-text="{{ stepsText }}"
        steps-goal-text="{{ stepsGoalText }}"
        steps-progress-width="{{ stepsProgressWidth }}"
        current-heart-rate="{{ currentHeartRate }}"
        heart-rate-data="{{ heartRateData }}"
        battery-percent="{{ batteryPercent }}"
        battery-width="{{ batteryWidth }}"
        battery-color="{{ batteryColor }}">
      </dashboardface>

      <text class="gesture-hint">{{ faceHint }}</text>
    </div>

    <!-- Full-screen notification overlay; kept inline (same pattern as dim/sleep covers) to avoid custom-component widget mapping issues. -->
    <div class="fullscreen-notify" if="{{ fullscreenNotifyVisible }}">
      <div class="notify-body-wrap" if="{{ fullscreenNotifyType !== 'call' }}">
        <div class="notify-app-row">
          <image class="notify-app-icon" src="{{ fullscreenNotifyAppIcon }}"></image>
          <text class="notify-app-name">{{ fullscreenNotifyAppName }}</text>
        </div>
        <text class="notify-content-text">{{ fullscreenNotifyContent }}</text>
      </div>

      <div class="notify-body-wrap call-wrap" if="{{ fullscreenNotifyType === 'call' }}">
        <text class="notify-contact">{{ fullscreenNotifyContact }}</text>
        <text class="notify-phone">{{ fullscreenNotifyPhone }}</text>
      </div>

      <div class="notify-actions">
        <text class="notify-btn ignore-btn" @click="handleNotifyIgnore">忽略</text>
        <text class="notify-btn hangup-btn {{ fullscreenNotifyHangUp ? 'hangup-gray' : '' }}" if="{{ fullscreenNotifyType === 'call' }}" @click="handleNotifyHangup">挂断</text>
      </div>
    </div>

    <!-- E: Dim cover makes lower-refresh mode visible in the simulator. -->
    <div class="dim-cover" if="{{ powerDimVisible }}" @click="wakeByUser">
      <text class="dim-text">{{ powerModeText }} · {{ powerRefreshText }}</text>
    </div>

    <!-- E: Sleep cover simulates screen-off; tap it to mimic raise-to-wake in the simulator. -->
    <div class="sleep-cover" if="{{ powerSleepVisible }}" @click="wakeByRaise">
      <text class="sleep-time">{{ displayHours }}:{{ displayMinutes }}</text>
      <text class="sleep-label">息屏模式</text>
      <text class="sleep-tip">点击模拟抬腕亮屏</text>
    </div>

  </div>
</template>

<script>
import battery from '@system.battery'
import router from '@system.router'
import watchData from '../../common/watch_data'
import powerManager from '../../common/power_manager'
import deviceSettings from '../../common/device_settings'
import pageMotion from '../../common/page_motion'
import notificationManager from '../../common/notification_manager'

var FACE_LIST = [
  {
    id: 'sport',
    name: '活力数字',
    background: '#000000',
    accent: '#0A84FF'
  },
  {
    id: 'simple',
    name: '极简霓虹',
    background: '#05060A',
    accent: '#00E5FF'
  },
  {
    id: 'dashboard',
    name: '运动仪表',
    background: '#080B10',
    accent: '#32D74B'
  }
]

function getFaceIndex(faceId) {
  for (var i = 0; i < FACE_LIST.length; i++) {
    if (FACE_LIST[i].id === faceId) {
      return i
    }
  }
  return 0
}

function makeFaceDots(index) {
  var dots = []
  for (var i = 0; i < FACE_LIST.length; i++) {
    dots.push({
      width: i === index ? 18 : 6,
      color: i === index ? FACE_LIST[index].accent : '#3A3A3C'
    })
  }
  return dots
}

export default {
  private: {
    faceIndex: 0,
    faceName: '活力数字',
    faceBackground: '#000000',
    faceAccent: '#0A84FF',
    faceHint: '左右滑动切换，长按选择表盘',
    faceDots: makeFaceDots(0),
    faceSportVisible: true,
    faceSimpleVisible: false,
    faceDashboardVisible: false,
    faceOpacity: 1,
    faceOffset: 0,
    touchStartX: 0,
    touchStartY: 0,
    touchMoved: false,
    displayMonth: 'JAN',
    displayDate: '01',
    displayWeek: 'MON',
    displayMinutes: '00',
    displayHours: '00',
    batteryPercent: 75,
    batteryWidth: '75%',
    batteryColor: '#30D158',
    heartRateData: [],
    currentHeartRate: 88,
    stepsText: '4,567',
    stepsGoalText: '6,000',
import brightness from '@system.brightness'
import sensor from '@system.sensor'

// Three power modes are enough for a watch demo and keep timer management simple.
var MODE_ACTIVE = 'ACTIVE'
var MODE_DIM = 'DIM'
var MODE_SLEEP = 'SLEEP'

var MODE_CONFIG = {
  ACTIVE: {
    label: '亮屏',
    hint: '1秒刷新',
    color: '#30D158',
    brightness: 210,
    keepScreenOn: true,
    timeInterval: 1000,
    heartInterval: 3000,
    batteryInterval: 60000
  },
  DIM: {
    label: '暗屏',
    hint: '5秒刷新',
    color: '#FFD60A',
    brightness: 60,
    keepScreenOn: true,
    timeInterval: 5000,
    heartInterval: 30000,
    batteryInterval: 120000
  },
  SLEEP: {
    label: '息屏',
    hint: '低频保活',
    color: '#8E8E93',
    brightness: 8,
    keepScreenOn: false,
    timeInterval: 60000,
    heartInterval: 0,
    batteryInterval: 0
  }
}

var DIM_AFTER_MS = 8000
var SLEEP_AFTER_MS = 15000
var raiseWakeCallback = null
var lastAcceleration = null
var lastWakeAt = 0

function getConfig(mode) {
  return MODE_CONFIG[mode] || MODE_CONFIG.ACTIVE
}

function callApi(api, params, name) {
  // System APIs may be unavailable in the simulator; failure should not break UI demo.
  try {
    if (api) {
      api(params)
    }
  } catch (e) {
    console.log(name + ' unavailable, use UI simulation')
  }
}

function handleAcceleration(data) {
  // A simple movement delta works as a raise-wake simulation on devices with an accelerometer.
  if (!raiseWakeCallback || !data) {
    return
  }

  var current = {
    x: data.x || 0,
    y: data.y || 0,
    z: data.z || 0
  }

  if (lastAcceleration) {
    var delta = Math.abs(current.x - lastAcceleration.x) + Math.abs(current.y - lastAcceleration.y) + Math.abs(current.z - lastAcceleration.z)
    var now = Date.now()
    if (delta > 5 && now - lastWakeAt > 3000) {
      lastWakeAt = now
      raiseWakeCallback()
    }
  }

  lastAcceleration = current
}

export default {
  MODE_ACTIVE: MODE_ACTIVE,
  MODE_DIM: MODE_DIM,
  MODE_SLEEP: MODE_SLEEP,

  getModeByIdle(idleMs) {
    if (idleMs >= SLEEP_AFTER_MS) {
      return MODE_SLEEP
    }
    if (idleMs >= DIM_AFTER_MS) {
      return MODE_DIM
    }
    return MODE_ACTIVE
  },

  getRefreshConfig(mode) {
    return getConfig(mode)
  },

  getUiState(mode) {
    var config = getConfig(mode)
    return {
      label: config.label,
      hint: config.hint,
      color: config.color,
      sleepVisible: mode === MODE_SLEEP,
      dimVisible: mode === MODE_DIM
    }
  },

